-- CUPS demo database (fictional data) for PostgreSQL
SET client_encoding = 'UTF8';
BEGIN;

DROP TABLE IF EXISTS order_items, orders, customers, promo_codes, products, cafes CASCADE;

CREATE TABLE cafes (
  cafe_id      text PRIMARY KEY,
  name         text NOT NULL,
  chain        text NOT NULL,
  district     text,
  address      text,
  lat          double precision,
  lng          double precision,
  prep_minutes integer
);

CREATE TABLE products (
  product_id text PRIMARY KEY,
  product    text NOT NULL,
  category   text NOT NULL,
  base_price integer NOT NULL,
  is_combo   boolean NOT NULL
);

CREATE TABLE promo_codes (
  code             text PRIMARY KEY,
  percent          integer NOT NULL,
  first_order_only boolean NOT NULL,
  scope            text
);

CREATE TABLE customers (
  customer_id   text PRIMARY KEY,
  first_name    text NOT NULL,
  last_name     text NOT NULL,
  gender        text,
  age_group     text,
  persona       text,
  platform      text,
  phone_masked  text,
  signup_date   date,
  home_cafe_id  text REFERENCES cafes (cafe_id),
  home_district text,
  segment       text
);

CREATE TABLE orders (
  order_id       text PRIMARY KEY,
  order_number   integer NOT NULL,
  pickup_code    text,
  cafe_id        text NOT NULL REFERENCES cafes (cafe_id),
  customer_id    text NOT NULL REFERENCES customers (customer_id),
  created_at     timestamp NOT NULL,
  date           date NOT NULL,
  weekday        text,
  hour           integer,
  status         text NOT NULL,
  cancelled_by   text,
  order_type     text,
  pickup_mode    text,
  pickup_at      timestamp,
  accepted_at    timestamp,
  ready_at       timestamp,
  picked_up_at   timestamp,
  cancelled_at   timestamp,
  prep_minutes   numeric(5,1),
  items_count    integer,
  subtotal       integer NOT NULL,
  promo_code     text REFERENCES promo_codes (code),
  discount       integer NOT NULL,
  total          integer NOT NULL,
  is_first_order boolean NOT NULL,
  platform       text
);

CREATE TABLE order_items (
  item_id       integer PRIMARY KEY,
  order_id      text NOT NULL REFERENCES orders (order_id),
  cafe_id       text NOT NULL REFERENCES cafes (cafe_id),
  product_id    text NOT NULL REFERENCES products (product_id),
  product       text NOT NULL,
  category      text,
  qty           integer NOT NULL,
  base_price    integer NOT NULL,
  options_price integer NOT NULL,
  unit_price    integer NOT NULL,
  line_total    integer NOT NULL,
  size          text,
  milk          text,
  syrup         text,
  sugar         text,
  options_text  text
);

-- cafes: 108 rows

-- products: 35 rows

-- promo_codes: 2 rows

-- customers: 1000 rows

-- orders: 10043 rows

-- order_items: 15926 rows

CREATE INDEX orders_cafe_idx     ON orders (cafe_id, created_at);
CREATE INDEX orders_customer_idx ON orders (customer_id);
CREATE INDEX orders_date_idx     ON orders (date);
CREATE INDEX items_order_idx     ON order_items (order_id);
CREATE INDEX items_product_idx   ON order_items (product_id);

COMMIT;
ANALYZE;
